/// <summary>
/// MPJ_5046_MetpayInterfaces 05/05/2021
/// UI builder required for validating and list partameters at initialisation
/// </summary>
public class METVendCrossDocFeeUIBuilder extends SysOperationAutomaticUIBuilder
{
    DialogField                     ledgerName;

}

Method.Source:
    /// <summary>
    /// MPJ_5046_MetpayInterfaces 05/05/2021
    /// Post build maps the dialog fields to contract
    /// </summary>
    public void postBuild()
    {
        super();

        ledgerName = this.bindInfo().getDialogField(this.dataContractObject(),
                                    methodStr(METVendCrossDocFeeContract, getLedgerName));
    }

/// <summary>
/// MPJ_5046_MetpayInterfaces 05/05/2021
/// postRun allows validation and hiding of methods
/// </summary>
public void postRun()
{
    super();

    ledgerName.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(METVendCrossDocFeeUIBuilder, ledgerNameLookUp), this);
}

    /// <summary>
    /// MPJ_5046_MetpayInterfaces 05/05/2021
    /// ledgerNameLookUp looks up
    /// </summary>
    /// <param name = "_control">object of data</param>
    public void ledgerNameLookUp(FormStringControl  _control)
    {
        Query						query = new Query();
        QueryBuildDataSource        qbd;
        SysTableLookup			    sysTableLookup;
        
        sysTablelookup = SysTableLookup::newParameters(tableNum(LedgerJournalName), _control);
        sysTablelookup.addLookupfield(fieldNum(LedgerJournalName,JournalName));
        sysTablelookup.addLookupfield(fieldNum(LedgerJournalName,Name));

        qbd = query.addDataSource(tableNum(LedgerJournalName));
        qbd.addSortField(fieldnum(LedgerJournalName, JournalName));
        
        sysTableLookup.parmQuery(query);
        sysTablelookup.performFormLookup();
    }
